<?php
declare(strict_types=1); require_once __DIR__.'/_shared.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $id=(int)($_POST['id']??0); if(($_POST['delete']??'')==='1'&&$id){ db()->prepare('DELETE FROM campaigns WHERE id=?')->execute([$id]); flash('Campaign deleted.'); redirect('campaigns.php'); } $v=[]; foreach(['product_id','name','tone','audience','content_angle','cta','hashtags','stock_terms','schedule_frequency','active'] as $f) $v[$f]=trim((string)($_POST[$f]??'')); $active=($_POST['active']??'0')==='1'?1:0; if($id) db()->prepare('UPDATE campaigns SET product_id=?,name=?,tone=?,audience=?,content_angle=?,cta=?,hashtags=?,stock_terms=?,schedule_frequency=?,active=?,updated_at=? WHERE id=?')->execute([$v['product_id'],$v['name'],$v['tone'],$v['audience'],$v['content_angle'],$v['cta'],$v['hashtags'],$v['stock_terms'],$v['schedule_frequency'],$active,now_utc(),$id]); else db()->prepare('INSERT INTO campaigns(product_id,name,tone,audience,content_angle,cta,hashtags,stock_terms,schedule_frequency,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$v['product_id'],$v['name'],$v['tone'],$v['audience'],$v['content_angle'],$v['cta'],$v['hashtags'],$v['stock_terms'],$v['schedule_frequency'],$active,now_utc(),now_utc()]); flash('Campaign saved.'); redirect('campaigns.php'); }
$products=db()->query('SELECT id,name FROM products ORDER BY name')->fetchAll(); $edit=null; if(isset($_GET['edit'])){ $st=db()->prepare('SELECT * FROM campaigns WHERE id=?'); $st->execute([(int)$_GET['edit']]); $edit=$st->fetch(); } $rows=db()->query('SELECT c.*,p.name product FROM campaigns c JOIN products p ON p.id=c.product_id ORDER BY c.active DESC,c.name')->fetchAll(); layout_header('Campaigns'); show_flash(); ?><div class="split"><section class="panel"><h2><?= $edit?'Edit':'Create' ?> campaign</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label>Product<select name="product_id" required><?php foreach($products as $p): ?><option value="<?=$p['id']?>" <?=($edit['product_id']??'')==$p['id']?'selected':''?>><?=h($p['name'])?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Campaign name<input name="name" required value="<?=h($edit['name']??'')?>"></label><label>Tone<input name="tone" value="<?=h($edit['tone']??'helpful, upbeat')?>"></label><label>Audience<input name="audience" value="<?=h($edit['audience']??'')?>"></label><label>Schedule frequency<input name="schedule_frequency" placeholder="daily, weekdays, 3/week" value="<?=h($edit['schedule_frequency']??'')?>"></label></div><label>Content angle<textarea name="content_angle"><?=h($edit['content_angle']??'')?></textarea></label><label>CTA<input name="cta" value="<?=h($edit['cta']??get_setting('default_cta'))?>"></label><label>Hashtags<input name="hashtags" value="<?=h($edit['hashtags']??get_setting('default_hashtags'))?>"></label><label>Stock video search terms<input name="stock_terms" value="<?=h($edit['stock_terms']??'vertical lifestyle, unboxing, desk setup')?>"></label><label>Active<select name="active"><option value="1" <?=($edit['active']??1)?'selected':''?>>Active</option><option value="0" <?=isset($edit)&&!$edit['active']?'selected':''?>>Inactive</option></select></label><button>Save campaign</button></form></section><section class="panel"><h2>Campaigns</h2><div class="table-wrap"><table><tr><th>Name</th><th>Product</th><th>Frequency</th><th>Active</th><th>Actions</th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r['name'])?></td><td><?=h($r['product'])?></td><td><?=h($r['schedule_frequency'])?></td><td><?=$r['active']?'Yes':'No'?></td><td><a href="?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="delete" value="1"><button class="danger" data-confirm="Delete campaign?">Delete</button></form></td></tr><?php endforeach; ?></table></div></section></div><?php layout_footer();
